changeSet.sql:
CREATE TABLE IF NOT EXISTS system_config ( id UUID PRIMARY KEY, config_key VARCHAR(100) UNIQUE NOT NULL, config_value TEXT NOT NULL, description VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(50), updated_by VARCHAR(50) );
-- Seed API configs INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f601', 'groq.api-key', '', 'API Key cho Groq AI Cloud Service', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f602', 'groq.model', 'llama-3.3-70b-versatile', 'Model AI chính dùng cho Groq', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f603', 'groq.fallback-models', 'llama-3.3-70b-versatile,llama-3.1-8b-instant', 'Các model fallback dự phòng cho Groq', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f604', 'groq.endpoint', 'https://api.groq.com/openai/v1/chat/completions', 'Endpoint API của Groq', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
-- Seed Prompt system instruction INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f605', 'prompt.pronunciation-system-instruction', 'Bạn là chuyên gia phân tích phát âm tiếng Việt. So sánh rawText với targetText và trả về nhận xét sư phạm, cụ thể, hữu ích. Hệ thống hiện tại hỗ trợ chẩn đoán và phân tích các lỗi phát âm/vùng miền sau:\n{availableErrorTags}\nHãy ưu tiên đối chiếu phát hiện lỗi xem người học có mắc phải lỗi nào trong danh sách trên hay không. Không được trả lời chung chung, không được lặp lại nguyên văn targetText, và không được dùng câu ngắn kiểu ''Phát âm chưa chính xác'' nếu chưa giải thích vì sao.', 'System Instruction chấm điểm phát âm', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
-- Seed Prompt JSON schema INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f606', 'prompt.pronunciation-schema-instruction', 'Trả về JSON thuần túy với các fields: accuracy (0-100), detectedError (mô tả lỗi cụ thể), feedback (ít nhất 2 câu, nêu lỗi và cách sửa), suggestion (gợi ý ngắn gọn), errorDetail (diễn giải chi tiết hơn feedback), isRegional (boolean), isCorrect (boolean), shapeKey (exact_match, near_match, pronunciation_mismatch, regional_error, missing_input).', 'Cấu trúc schema JSON đầu ra', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
-- Seed Quiz Explanation INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f607', 'prompt.quiz-explanation', 'Bạn là giáo viên dạy Tiếng Việt vui nhộn và tận tâm. Hãy giải thích ngắn gọn (1-3 câu) lý do vì sao đáp án là {status}. {timeoutDetail} Câu hỏi: "{question}". Người dùng chọn: "{selectedAnswer}". Đáp án đúng là: "{correctAnswer}". Kỹ năng: {skillType}. {hearingDetail} {correctDetail} Hãy giúp người dùng hiểu rõ kiến thức một cách thân thiện. Trả về JSON có field ''explanation''.', 'Template giải thích câu hỏi Quiz', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
-- Seed Entry Test Feedback INSERT INTO system_config (id, config_key, config_value, description, created_by, updated_by) VALUES ('8f5a6b0c-7b0a-41f2-9de9-52e6d622f608', 'prompt.entry-test-feedback', 'Học viên mắc các lỗi sau trong phát âm: {errorDetails} Hãy viết 1 đoạn 3-4 câu nhận xét ngắn gọn, cổ vũ học viên và khuyên học viên nên ưu tiên học lỗi nào trước (dựa trên % độ chính xác thấp nhất). Trả về kết quả dưới dạng JSON có trường ''reply''.', 'Template nhận xét bài đánh giá năng lực đầu vào', 'SYSTEM', 'SYSTEM') ON CONFLICT (config_key) DO NOTHING;
